-- V-K2 (run O1, session.sh): after 021d-k2-idols.sql, lot K2 (new idols of the groups with none, and the unreserved yes of 021b).
-- Read only, in a read-only transaction. Each row is: ok or KO | what | the number found. Never a name, an e-mail or a row of a person.
-- Expected numbers come from scripts/kpop/k2/data/k2-idols.json: 91 new idols in 18 groups, 11 activations.
begin transaction read only;
with k(group_slug, qid) as (values ('loona', 'Q56259179'), ('loona', 'Q48893612'), ('loona', 'Q57318729'), ('loona', 'Q56824821'), ('loona', 'Q56816418'), ('loona', 'Q56825122'), ('loona', 'Q58224261'), ('loona', 'Q58825704'), ('loona', 'Q58825794'), ('loona', 'Q58825825'), ('got7', 'Q16075083'), ('got7', 'Q491048'), ('got7', 'Q16905948'), ('got7', 'Q492313'), ('got7', 'Q17500581'), ('got7', 'Q16688282'), ('got7', 'Q17500887'), ('monsta-x', 'Q24834621'), ('monsta-x', 'Q28746303'), ('monsta-x', 'Q27951584'), ('monsta-x', 'Q28549791'), ('monsta-x', 'Q23008017'), ('monsta-x', 'Q28549782'), ('girls-generation', 'Q233371'), ('girls-generation', 'Q233894'), ('girls-generation', 'Q236355'), ('girls-generation', 'Q253619'), ('girls-generation', 'Q276158'), ('girls-generation', 'Q233385'), ('girls-generation', 'Q466975'), ('girls-generation', 'Q240082'), ('zerobaseone', 'Q115933814'), ('zerobaseone', 'Q117746200'), ('zerobaseone', 'Q117817675'), ('zerobaseone', 'Q117818064'), ('mamamoo', 'Q19483969'), ('mamamoo', 'Q19483782'), ('mamamoo', 'Q19603930'), ('mamamoo', 'Q19603912'), ('bigbang', 'Q482991'), ('bigbang', 'Q495577'), ('bigbang', 'Q194798'), ('katseye', 'Q124692767'), ('katseye', 'Q124692773'), ('katseye', 'Q124692741'), ('katseye', 'Q124692787'), ('katseye', 'Q124692753'), ('illit', 'Q126923756'), ('illit', 'Q126923757'), ('illit', 'Q126923760'), ('illit', 'Q126923761'), ('treasure', 'Q63850969'), ('treasure', 'Q97319986'), ('treasure', 'Q98136886'), ('treasure', 'Q97320177'), ('treasure', 'Q97352003'), ('treasure', 'Q97326265'), ('treasure', 'Q97352009'), ('dreamcatcher', 'Q59313184'), ('dreamcatcher', 'Q59313270'), ('dreamcatcher', 'Q59313326'), ('dreamcatcher', 'Q59313384'), ('dreamcatcher', 'Q59313479'), ('dreamcatcher', 'Q59313527'), ('dreamcatcher', 'Q59313606'), ('tws', 'Q132041926'), ('tws', 'Q125865775'), ('tws', 'Q132041928'), ('tws', 'Q132041929'), ('tws', 'Q124091988'), ('tws', 'Q132041931'), ('p1harmony', 'Q114690500'), ('p1harmony', 'Q121579075'), ('p1harmony', 'Q121579089'), ('p1harmony', 'Q121579375'), ('p1harmony', 'Q30006465'), ('cortis', 'Q135963716'), ('cortis', 'Q135963733'), ('cortis', 'Q135963739'), ('hearts2hearts', 'Q131932320'), ('hearts2hearts', 'Q131932322'), ('hearts2hearts', 'Q131932323'), ('team', 'Q116226143'), ('team', 'Q104723121'), ('team', 'Q127427815'), ('akmu', 'Q16071030'), ('akmu', 'Q18697707'), ('astro', 'Q47673408'), ('astro', 'Q60991892'), ('astro', 'Q21060390'), ('astro', 'Q56278318')
), act(id, qid) as (values (82, 'Q26451151'), (89, 'Q60644128'), (133, 'Q109108660'), (143, 'Q123554436'), (144, 'Q123554438'), (145, 'Q123554439'), (148, 'Q123560890'), (151, 'Q123310101'), (152, 'Q123528880'), (153, 'Q123528897'), (163, 'Q117178583')
), mine as (
  select i.* from k join public.groups g on g.slug = k.group_slug join public.idols i on i.group_id = g.id and i.wikidata_qid = k.qid
), cap as (
  select s.*, (select count(*) from public.dle_attributes a where a.game_id = 'kpopdle-idol' and coalesce(cardinality(public.dle_values(s.attrs -> a.key -> 'v')), 0) = 0) as missing
  from public.dle_src_kpop_idol s
)
select case when ok is true then 'ok' else 'KO' end, what, coalesce(got, '-') from (values
  (1, 'idols K2 présentes : 91', (select count(*) = 91 from mine), (select count(*)::text from mine)),
  (2, 'idols K2 actives et relues : 91', (select count(*) = 91 from mine where active and not needs_review and detached_at is null), (select count(*)::text from mine where active and not needs_review and detached_at is null)),
  (3, 'idols K2 complètes (naissance, genre, début, nationalité) : 91', (select count(*) = 91 from mine where birth_date is not null and gender in ('female', 'male') and debut_year is not null and nullif(btrim(nationality), '') is not null), (select count(*)::text from mine where birth_date is not null and gender in ('female', 'male') and debut_year is not null and nullif(btrim(nationality), '') is not null)),
  (4, 'idols K2 sans source de naissance, genre, début ou nationalité : 0', (select count(*) = 0 from mine m where not (exists (select 1 from public.entity_sources e where e.entity_type = 'idol' and e.entity_id = m.id::text and e.field = 'birth_date') and exists (select 1 from public.entity_sources e where e.entity_type = 'idol' and e.entity_id = m.id::text and e.field = 'gender') and exists (select 1 from public.entity_sources e where e.entity_type = 'idol' and e.entity_id = m.id::text and e.field = 'debut_year') and exists (select 1 from public.entity_sources e where e.entity_type = 'idol' and e.entity_id = m.id::text and e.field = 'nationality'))), (select count(*)::text from mine m where not (exists (select 1 from public.entity_sources e where e.entity_type = 'idol' and e.entity_id = m.id::text and e.field = 'birth_date') and exists (select 1 from public.entity_sources e where e.entity_type = 'idol' and e.entity_id = m.id::text and e.field = 'gender') and exists (select 1 from public.entity_sources e where e.entity_type = 'idol' and e.entity_id = m.id::text and e.field = 'debut_year') and exists (select 1 from public.entity_sources e where e.entity_type = 'idol' and e.entity_id = m.id::text and e.field = 'nationality')))),
  (5, 'mineurs ou sans date de naissance parmi les idols actives : 0', (select count(*) = 0 from public.idols where active and (birth_date is null or birth_date > current_date - interval '18 years')), (select count(*)::text from public.idols where active and (birth_date is null or birth_date > current_date - interval '18 years'))),
  (6, 'idols de 021b activées : 11', (select count(*) = 11 from act a join public.idols i on i.id = a.id and i.wikidata_qid = a.qid where i.active and not i.needs_review), (select count(*)::text from act a join public.idols i on i.id = a.id and i.wikidata_qid = a.qid where i.active and not i.needs_review)),
  (7, 'groupes K2 avec une agence et une génération : 18', (select count(*) = 18 from public.groups g where g.slug in ('loona', 'got7', 'monsta-x', 'girls-generation', 'zerobaseone', 'mamamoo', 'bigbang', 'katseye', 'illit', 'treasure', 'dreamcatcher', 'tws', 'p1harmony', 'cortis', 'hearts2hearts', 'team', 'akmu', 'astro') and nullif(btrim(g.record_label), '') is not null and nullif(btrim(g.generation), '') is not null), (select count(*)::text from public.groups g where g.slug in ('loona', 'got7', 'monsta-x', 'girls-generation', 'zerobaseone', 'mamamoo', 'bigbang', 'katseye', 'illit', 'treasure', 'dreamcatcher', 'tws', 'p1harmony', 'cortis', 'hearts2hearts', 'team', 'akmu', 'astro') and nullif(btrim(g.record_label), '') is not null and nullif(btrim(g.generation), '') is not null)),
  (10, 'groupes supplémentaires des membres de plusieurs groupes : 8', (select count(*) = 8 from public.idol_other_groups x join mine m on m.id = x.idol_id), (select count(*)::text from public.idol_other_groups x join mine m on m.id = x.idol_id)),
  (8, 'idols K2 prêtes comme cible dans la vue du jeu : 91', (select count(*) = 91 from cap c join mine m on m.id::text = c.entity_id where c.missing = 0), (select count(*)::text from cap c join mine m on m.id::text = c.entity_id where c.missing = 0)),
  (9, 'idols assez complètes pour être cible, au total (information)', true, (select count(*)::text from cap where missing = 0))
) as c(n, what, ok, got) order by n;
rollback;
